#!/bin/bash
#
# Builds the release source packages and notes.
#
# Usage: create_release_pkg_artifacts.sh <project_dir> <tag> [notes]
#
# Writes release/fluentcpp-<tag>.tar.gz, release/fluentcpp-<tag>.zip,
# release/install.sh and release/notes.md (which lists install.sh's SHA-256). The changelog itself is generated by the GitHub release.

set -euo pipefail

PROJECT_DIR=$1
TAG=$2
NOTES=${3:-}

cd "${PROJECT_DIR}"

rm -fr release
mkdir -p release/src

# Ship only what is needed to build and install the library. Tests,
# benchmarks, examples and docs are opt-in subdirectories and are left out.
cp -f CMakeLists.txt LICENSE README.md release/src
cp -rf cmake include src release/src
cp -f scripts/install.sh release/src

# install.sh is also a release asset, and its hash goes in the notes so readers
# can check it before running (see the README).
cp -f scripts/install.sh release/install.sh
INSTALL_SHA256=$(sha256sum release/install.sh | awk '{print $1}')

{
  [ -n "${NOTES}" ] && printf '%s\n\n' "${NOTES}"
  printf 'install.sh SHA-256: `%s`\n' "${INSTALL_SHA256}"
} > release/notes.md

PKG_NAME="fluentcpp-${TAG}"

tar -czf "release/${PKG_NAME}.tar.gz" -C release/src .
(cd release/src && zip -qr "../${PKG_NAME}.zip" .)
rm -fr release/src
